const s = wb.getWorksheet('Sheet1');
const vals = s.getRange('A1:B82').getValues();
const isBlank = (r) => r[0] === null || r[0] === undefined || r[0] === '';
const cmp = (a, b) => { const x = String(a[0]).toLowerCase(), y = String(b[0]).toLowerCase(); return x < y ? -1 : x > y ? 1 : 0; };
let i = 0; const blocks = [];
while (i < vals.length) {
  if (isBlank(vals[i])) { i++; continue; }
  let j = i; while (j < vals.length && !isBlank(vals[j])) j++;
  // row i is the block's header; data is rows i+1..j-1 (0-based)
  const data = vals.slice(i + 1, j).map((r, k) => ({ r, k }));
  data.sort((a, b) => cmp(a.r, b.r) || a.k - b.k);
  const sorted = data.map(d => d.r.map(v => "'" + v));
  s.getRange(`A${i + 2}:B${j}`).setValues(sorted);
  blocks.push(`A${i + 2}:B${j}`);
  i = j;
}
log(blocks.join(', '));
